import{_ as i,o as t,c as a,a3 as o}from"./chunks/framework.BwzYn71E.js";const u=JSON.parse('{"title":"Digital Circuits","description":"","frontmatter":{"translationSource":{"title":"数字电路","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Yh0HLXCoQQ27V3mZ1Nxpyg","scope":"page"},"translationLang":"en","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/digital-circuits"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/digital-circuits"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/digital-circuits"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/digital-circuits"}]]},"headers":[],"relativePath":"digital-circuits.md","filePath":"logistics/src/page-Yh0HLXCoQQ27V3mZ1Nxpyg.md"}'),n={name:"digital-circuits.md"};function r(s,e,l,c,p,d){return t(),a("div",null,[...e[0]||(e[0]=[o('<div class="logistics-content"><h1 id="digital-circuits" tabindex="-1">Digital Circuits <a class="header-anchor" href="#digital-circuits" aria-label="Permalink to &quot;Digital Circuits&quot;">​</a></h1><p class="page-updated" data-update-status="recorded"><span>Content updated: </span><a href="/endfield-skydoc/changelog/capture-2026-11-14T07-40-38-165Z-a1e1e549" title="Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record." aria-label="Content updated: 2026-11-14. Date when the mirror captured this page’s latest content change (China Standard Time), not the author’s edit time. View the update record."><time datetime="2026-11-14T07:40:39.277Z">2026-11-14</time></a><span class="page-updated-zone"> (China Standard Time)</span></p><blockquote><p>Source page ID: <code>Yh0HLXCoQQ27V3mZ1Nxpyg</code> | <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=Yh0HLXCoQQ27V3mZ1Nxpyg" target="_blank" rel="noreferrer">Open in Tencent Docs</a></p></blockquote><p>The following is the group owner&#39;s responsibility.</p><p><span id="source-block-YZ6VeUpQiBgrSopI5kB9Ua"></span></p><h2 id="digital-circuit-control-system" tabindex="-1">Digital-Circuit Control System <a class="header-anchor" href="#digital-circuit-control-system" aria-label="Permalink to &quot;Digital-Circuit Control System&quot;">​</a></h2><p><span id="source-block-EnP43uHPu7gRUdMRKQOpSk"></span></p><h3 id="generating-periodic-point-signals" tabindex="-1">Generating Periodic Point Signals <a class="header-anchor" href="#generating-periodic-point-signals" aria-label="Permalink to &quot;Generating Periodic Point Signals&quot;">​</a></h3><p>As shown, <a href="/endfield-skydoc/basic-factory-principles#source-block-7R9931VccE38fQGWecdJ9R">Basic Factory Principles</a> allows one Ferrium Ore output every 100 seconds.</p><p>Define a downstream-flowing logistics stream called a point-signal stream. Once stable, every downstream output interval is a multiple of the largest possible fixed interval T, where T is quite large. The Ferrium Ore line above is plainly such a stream, with T = 100s. Call T its clock period and 1/T its clock frequency f, here 10mHz.</p><p><span id="source-block-z2Za4dfyLVXsRqMMoPrgK3"></span></p><h3 id="clock-sampling" tabindex="-1">Clock Sampling <a class="header-anchor" href="#clock-sampling" aria-label="Permalink to &quot;Clock Sampling&quot;">​</a></h3><p>Feedback requires converting the source&#39;s flow state into digital signals 0 and 1, with 0 meaning inactive and 1 active. One idea is to regularize the source output, concentrating its output within each clock period into the same part of that period, for example:</p><p>1010101010——&gt;1110011000</p><p>The result in <a href="/endfield-skydoc/logistics-principles-and-frontier-research#source-block-f5f4WE5OyQHLDbhWbKgmAv">Logistics Principles and Some Terms</a> lets us construct the illustrated device to meet this requirement.</p><p>Sampling one point in a clock period then compares the source&#39;s total output over an interval with a set value: greater output gives sample 1; otherwise 0. The sample point&#39;s position within the clock period determines this threshold.</p><p>The sampling device is easy to build, as shown:</p><p><span id="source-block-JuE8e1LcfMB49QplhfUWqT"></span></p><h3 id="signal-amplification" tabindex="-1">Signal Amplification <a class="header-anchor" href="#signal-amplification" aria-label="Permalink to &quot;Signal Amplification&quot;">​</a></h3><p>We sometimes need multiple uses of a point signal. Applying binary complementation twice copies a flow. This can be integrated into the following signal amplifier, each output producing a copied signal:</p><p><span id="source-block-HHuZkGBvhHGd7puOwrgATO"></span></p><h3 id="signal-operations" tabindex="-1">Signal Operations <a class="header-anchor" href="#signal-operations" aria-label="Permalink to &quot;Signal Operations&quot;">​</a></h3><p>Protocol Stash priorities permit logical operations on point signals, following exactly the simple-logic rules in <a href="/endfield-skydoc/basic-factory-principles#source-block-EHhBNcPi9z2GuxnXC3X587">Basic Factory Principles</a>. Here 1 means the point-signal stream outputs one item in the clock period, and 0 means no item.</p><p>Take particular care: if no AND follows the final NOT, the resulting signal is an almost-full complementary belt and fails the point-signal requirement. Add an AND with a high-level signal.</p><p><span id="source-block-x3ZJ3xNYB6VgMGagCAaz3A"></span></p><h3 id="signal-reconstruction" tabindex="-1">Signal Reconstruction <a class="header-anchor" href="#signal-reconstruction" aria-label="Permalink to &quot;Signal Reconstruction&quot;">​</a></h3><p>After logical operations, convert the result into output. Here an output signal means downstream will not continuously receive reaction inputs in the current period. The illustrated device performs this function:</p><p>When Ferrium Ore representing the computed output enters the Protocol Stash, the stash blocks and batteries cannot pass through. Its complementary belt reaches the stash output after a one-period delay. If the computed signal has stopped, Ferrium Ore exits, unblocking the stash, and batteries output continuously during the next period. Otherwise Ferrium Ore enters and exits simultaneously, leaving one Ferrium Ore in the stash; blocking persists and batteries cannot output.</p><p><span id="source-block-fc6GxHsFbpcKbKS9i9cPX6"></span></p><h3 id="improving-performance-with-delay-devices" tabindex="-1">Improving Performance with Delay Devices <a class="header-anchor" href="#improving-performance-with-delay-devices" aria-label="Permalink to &quot;Improving Performance with Delay Devices&quot;">​</a></h3><p>The filter in <a href="/endfield-skydoc/logistics-principles-and-frontier-research#source-block-f5f4WE5OyQHLDbhWbKgmAv">Logistics Principles and Some Terms</a> uses very many reaction components and considerable space, making practical use difficult. Signal reconstruction also needs a one-period delay, requiring a very long belt. A flow limiter with internal circulation can supply a delay; this, for example, is a 100s delay device:</p><p>It simplifies the reconstruction delay. A high-level point signal of period 2T together with a signal reconstruction device delayed by T can produce a standard square wave of period 2T. With this square wave, the sampler&#39;s filter can be simplified as follows, greatly reducing its footprint and component count:</p></div>',1)])])}const g=i(n,[["render",r]]);export{u as __pageData,g as default};
